select pg_temp.expect_error($s$select public.save_event_picklist('10000000-0000-0000-0000-000000000091',1,jsonb_set(pg_temp.state(),'{profiles,offense,weights,fuel}','-1'))$s$,'23514');
select pg_temp.expect_error($s$select public.save_event_picklist('10000000-0000-0000-0000-000000000091',1,jsonb_set(pg_temp.state(),'{manualOrder}','[999999]'))$s$,'23514');
