select pg_temp.expect_error($s$select public.save_event_picklist('10000000-0000-0000-0000-000000000091',1,pg_temp.state())$s$,'40001');
select public.create_picklist_snapshot('10000000-0000-0000-0000-000000000091',2,'Before selection','{"version":1}');
